import { useEffect, useState } from "react";
import MenuGrid from "./MenuGrid";
import Cart from "./Cart";
import UserOrders from "./UserOrders";
import Recommendations from "./Recommendations";
import PaymentModal from "./PaymentModal";
import { useAuth } from "../../context/AuthContext";
import "../../styles/canteen-ui.css";

export default function UserPanel() {
  const { user, logout } = useAuth();

  const [activeTab, setActiveTab] = useState("home");
  const [cart, setCart] = useState([]);
  const [orders, setOrders] = useState([]);
  const [menu, setMenu] = useState([]);
  const [showPayment, setShowPayment] = useState(false);

  /* ================= CART LOGIC ================= */

  const addToCart = (item) => {
    setCart((prev) => {
      const existing = prev.find((i) => i.id === item.id);
      if (existing) {
        return prev.map((i) =>
          i.id === item.id
            ? { ...i, quantity: i.quantity + 1 }
            : i
        );
      }
      return [...prev, { ...item, quantity: 1 }];
    });
  };

  const removeFromCart = (itemId) => {
    setCart((prev) =>
      prev
        .map((i) =>
          i.id === itemId
            ? { ...i, quantity: i.quantity - 1 }
            : i
        )
        .filter((i) => i.quantity > 0)
    );
  };

  /* ================= LOAD MENU ================= */

  useEffect(() => {
    if (!user) return;

    fetch(`http://localhost:8000/api/menu/?college=${user.college}`)
      .then((res) => res.json())
      .then(setMenu)
      .catch((err) => console.error("Menu load failed", err));
  }, [user]);

  /* ================= LOAD ORDERS ================= */

  useEffect(() => {
    if (!user) return;

    fetch(`http://localhost:8000/api/orders/?user=${user.username}`)
      .then((res) => res.json())
      .then((data) => {
        setOrders(
          Array.isArray(data)
            ? data.sort((a, b) => b.order_id - a.order_id)
            : []
        );
      })
      .catch((err) => console.error("Orders load failed", err));
  }, [user]);

  /* ================= FINALIZE ORDER ================= */

  const finalizeOrder = async () => {
    if (!user || cart.length === 0) return;

    const items = cart;
    const total = items.reduce(
      (sum, i) => sum + i.price * i.quantity,
      0
    );
    const order_id = Date.now();

    setOrders((prev) => [
      { order_id, items, total, status: "Pending" },
      ...prev,
    ]);

    try {
      await fetch("http://localhost:8000/api/orders/create/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          order_id,
          user: user.username,
          items,
          total,
        }),
      });

      setCart([]);

      fetch(`http://localhost:8000/api/orders/?user=${user.username}`)
        .then((res) => res.json())
        .then((data) => {
          setOrders(
            Array.isArray(data)
              ? data.sort((a, b) => b.order_id - a.order_id)
              : []
          );
        });
    } catch (err) {
      console.error("Order failed", err);
    }
  };

  /* ================= PAYMENT ================= */

  const startPayment = () => {
    if (cart.length === 0) return;
    setShowPayment(true);
  };

  const handlePaymentSuccess = () => {
    setShowPayment(false);
    finalizeOrder();
    setActiveTab("orders");
  };

  const handlePaymentCancel = () => {
    setShowPayment(false);
  };

  if (!user) return null;

  const totalAmount = cart.reduce(
    (sum, i) => sum + i.price * i.quantity,
    0
  );

  /* ================= UI ================= */

  return (
    <div>
      {/* HEADER */}
      <header className="user-header">
        <div>
          <h2>Welcome {user.username}</h2>
          <p className="college-text">College: {user.college}</p>
        </div>

        <div className="icon-bar">
          {["home", "menu", "cart", "orders"].map((tab) => (
            <div
              key={tab}
              className={`icon-btn ${activeTab === tab ? "active" : ""}`}
              onClick={() => setActiveTab(tab)}
            >
              <span>{tab}</span>
            </div>
          ))}

          <button className="logout-btn" onClick={logout}>
            Logout
          </button>
        </div>
      </header>

      {activeTab === "menu" && (
        <>
          <Recommendations addToCart={addToCart} />
          <MenuGrid
            menu={menu}
            cart={cart}
            addToCart={addToCart}
            removeFromCart={removeFromCart}
          />
        </>
      )}

      {activeTab === "cart" && (
        <Cart
          cart={cart}
          removeFromCart={removeFromCart}
          placeOrder={startPayment}
        />
      )}

      {activeTab === "orders" && (
        <UserOrders orders={orders} user={user} />
      )}

      {showPayment && (
        <PaymentModal
          total={totalAmount}
          onCancel={handlePaymentCancel}
          onSuccess={handlePaymentSuccess}
        />
      )}
    </div>
  );
}
